'use strict';
const $=id=>document.getElementById(id),TOTAL=levels.length;
const normalize=v=>v.toLowerCase().replace(/[^a-z0-9]/g,'');
const hash=v=>{let h=2166136261;for(const c of normalize(v))h=Math.imul(h^c.charCodeAt(0),16777619);return(h>>>0).toString(16)};
let state={solved:0,current:0},storageOK=true;
try{let s=JSON.parse(localStorage.getItem('nadir-code-hard-v2'));if(s&&Number.isInteger(s.solved)&&s.solved>=0&&s.solved<=TOTAL){state.solved=s.solved;state.current=Number.isInteger(s.current)?Math.max(0,Math.min(s.current,Math.min(s.solved,TOTAL-1))):Math.min(s.solved,TOTAL-1)}}catch{storageOK=false}
const el=(tag,cls,text)=>{let e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e};
function button(text,fn,cls='mechanism-button'){const b=el('button',cls,text);b.type='button';b.onclick=fn;return b}
function save(){try{localStorage.setItem('nadir-code-hard-v2',JSON.stringify(state))}catch{storageOK=false}$('saveStatus').textContent=storageOK?'SAVED ON THIS DEVICE':'SAVING UNAVAILABLE'}
function route(){return '#/transmission/'+String(state.current+1).padStart(2,'0')+(state.current===1?'?parcel=6f.72.69.6f.6e&status=delivered':'')}
function syncRoute(){try{history.replaceState(null,'',location.pathname+location.search+route())}catch{}}
function image(src,alt){const i=el('img');i.src=src;i.alt=alt;i.loading='eager';i.addEventListener('error',()=>{const p=el('p','image-error','The artwork did not load. Reload this page before continuing.');i.replaceWith(p)});return i}
function artStudy(src,alt){const frame=el('div','art-frame');frame.append(image(src,alt));return frame}
function table(headers,rows){const t=el('table','puzzle-table'),thead=el('thead'),tr=el('tr');headers.forEach(x=>tr.append(el('th',null,x)));thead.append(tr);const body=el('tbody');rows.forEach(row=>{const r=el('tr');row.forEach(x=>r.append(el('td',null,x)));body.append(r)});t.append(thead,body);return t}
function render(){let i=state.current,l=levels[i];document.title='Nadir Code / '+String(i+1).padStart(2,'0')+' — '+l.title;$('levelNumber').textContent=String(i+1).padStart(2,'0');$('category').textContent='CASE '+String(i+1).padStart(2,'0')+' / UNCLASSIFIED';$('difficulty').textContent='HARD EDITION';$('puzzleTitle').textContent=l.title;$('puzzleIntro').textContent=l.intro;$('evidence').replaceChildren();renderMechanism(l,$('evidence'));$('instruction').textContent=l.prompt;$('answer').value='';$('answerForm').hidden=i<state.solved;$('feedback').classList.remove('error');$('feedback').textContent=i<state.solved?'Case closed. Your next unopened case is on the map.':'';$('solvedCount').textContent=state.solved+' / '+TOTAL+' SOLVED';$('progressText').textContent=state.solved===TOTAL?'THE DESCENT IS COMPLETE':state.solved?'DESCENT IN PROGRESS':'YOU ARE AT THE SURFACE';$('levelMap').replaceChildren(...levels.map((l,j)=>{const b=button(String(j+1).padStart(2,'0')+(j<state.solved?' ✓':''),()=>{state.current=j;render()},j===i?'active':j<state.solved?'solved':'');b.disabled=j>state.solved;b.setAttribute('aria-label','Level '+(j+1)+(j>state.solved?' locked':j<state.solved?' solved: '+l.title:': '+l.title));if(j===i)b.setAttribute('aria-current','step');return b}));if(state.solved===TOTAL)$('feedback').textContent='20 cases closed. The afterimage is yours. You have reached the bottom.';save();syncRoute()}
function submitAnswer(value){if(typeof value!=='string'||value.length>100||!normalize(value))return{correct:false,message:'An answer is required.'};if(state.current<state.solved)return{correct:false,message:'Already solved.'};if(hash(value)!==answerHashes[state.current]){$('feedback').textContent='The lock stays closed.';$('feedback').classList.add('error');return{correct:false,message:'No match.'}}const n=state.current+1;state.solved=n;state.current=Math.min(n,TOTAL-1);render();if(n<TOTAL){$('feedback').textContent='Case '+String(n).padStart(2,'0')+' closed. The next case is open.';$('answer').focus({preventScroll:true})}return{correct:true,solved:n,complete:n===TOTAL}}
$('answerForm').onsubmit=e=>{e.preventDefault();submitAnswer($('answer').value)};
$('guideButton').onclick=()=>$('guide').showModal();$('closeGuide').onclick=$('readyButton').onclick=()=>$('guide').close();$('restartButton').onclick=()=>$('resetDialog').showModal();$('cancelReset').onclick=()=>$('resetDialog').close();$('confirmReset').onclick=()=>{state={solved:0,current:0};render();$('resetDialog').close()};
$('creditsButton').onclick=()=>$('credits').showModal();$('closeCredits').onclick=()=>$('credits').close();
function readRoute(){const match=location.hash.match(/^#\/transmission\/(\d+)/);if(match){const n=Number(match[1])-1;if(n>=0&&n<TOTAL&&n<=state.solved)state.current=n}render()}
window.addEventListener('hashchange',readRoute);readRoute();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'submit_puzzle_answer',description:'Submit an answer for the current Nadir Code case. Correct answers save progress and open the next case.',inputSchema:{type:'object',properties:{answer:{type:'string',maxLength:100}},required:['answer'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||typeof input.answer!=='string')throw new Error('An answer string is required.');return submitAnswer(input.answer)}},{signal:lifecycle.signal})).catch(()=>{})}catch{}}
